def kissing_number11() -> np.ndarray:
    """
    Constructs a collection of 11-dimensional points with integral coordinates such that their maximum norm is smaller than their minimum pairwise distance, aiming to maximize the number of points.

    Returns:
        points: np.ndarray of shape (num_points,11)
    """
    d = 11
    # Generate lattice shell points of radius r
    r = 5  # Example radius; adjust to optimize later
    points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            for z in range(-r, r + 1):
                for w in range(-r, r + 1):
                    for u in range(-r, r + 1):
                        for v in range(-r, r + 1):
                            for a in range(-r, r + 1):
                                for b in range(-r, r + 1):
                                    for c in range(-r, r + 1):
                                        for d in range(-r, r + 1):
                                            for e in range(-r, r + 1):
                                                point = np.array([x, y, z, w, u, v, a, b, c, d, e])
                                                if np.linalg.norm(point) == r:
                                                    points.append(point)
    points = np.array(points).astype(np.int64)

    # Filter points to satisfy the constraint
    filtered_points = []
    for i, p_i in enumerate(points):
        valid = True
        for j, p_j in enumerate(filtered_points):
            if np.linalg.norm(p_i - p_j) <= np.linalg.norm(p_i):
                valid = False
                break
        if valid:
            filtered_points.append(p_i)

    return np.array(filtered_points)


